scan_table_check.script:
(function(engine, current) {
    var messages = new global.EcsUpdateSet(current).criticalChanges();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-CFG-008',
        title: 'Change to a protected component',
        recommendation: 'Confirm the change was approved by the component\'s owner group before the update set is promoted, or have a member of that group make the change. Manage the list in the ECS Protected Component table (role u_ecs_protected_component_user).',
        current: current
    });
    for (var i = 0; i < messages.length; i++) {
        report.addRecord(messages[i]);
    }
    engine.finding.setCurrentSource(current);
    report.flush();
})(engine, current);
